import numpy as np, random
inp=[[8,7,7],[2,7,5],[6,3,4]]
base=sum(inp,[])*3

def grid_from_rest(rest):
 o=[]; k=0
 for r in range(6):
  row=[]
  for c in range(6):
   if r<3 and c<3: row.append(inp[r][c])
   else: row.append(int(rest[k])); k+=1
  o.append(row)
 return o
